def make_int32_list_list(values):
    rows = [list(row) for row in values]
    row_buffers = [(ctypes.c_int32 * len(row))(*[int(value) for value in row]) for row in rows]
    items = (ifcopenshell_int32_list_t * len(row_buffers))()
    for index, buffer in enumerate(row_buffers):
        items[index].items = buffer
        items[index].size = len(buffer)
    result = ifcopenshell_int32_list_list_t()
    result.items = items
    result.size = len(items)
    result._keepalive = (items, row_buffers)  # type: ignore[attr-defined]
    return result


def make_int32_list_list_list(values):
    faces = [[list(loop) for loop in face] for face in values]
    loop_buffers = [
        [(ctypes.c_int32 * len(loop))(*[int(value) for value in loop]) for loop in face] for face in faces
    ]
    face_items = (ifcopenshell_int32_list_list_t * len(loop_buffers))()
    loop_items = []
    for face_index, loops in enumerate(loop_buffers):
        loops_array = (ifcopenshell_int32_list_t * len(loops))()
        for loop_index, buffer in enumerate(loops):
            loops_array[loop_index].items = buffer
            loops_array[loop_index].size = len(buffer)
        face_items[face_index].items = loops_array
        face_items[face_index].size = len(loops_array)
        loop_items.append(loops_array)
    result = ifcopenshell_int32_list_list_list_t()
    result.items = face_items
    result.size = len(face_items)
    result._keepalive = (face_items, loop_items, loop_buffers)  # type: ignore[attr-defined]
    return result


def make_int32_list_list_list_list(values):
    items = [make_int32_list_list_list(item) for item in values]
    item_array = (ifcopenshell_int32_list_list_list_t * len(items))(*items)
    result = ifcopenshell_int32_list_list_list_list_t()
    result.items = item_array
    result.size = len(item_array)
    result._keepalive = (item_array, items)  # type: ignore[attr-defined]
    return result


def make_double_list_list(values):
    rows = [list(row) for row in values]
    row_buffers = [(ctypes.c_double * len(row))(*[float(value) for value in row]) for row in rows]
    items = (ifcopenshell_double_list_t * len(row_buffers))()
    for index, buffer in enumerate(row_buffers):
        items[index].items = buffer
        items[index].size = len(buffer)
    result = ifcopenshell_double_list_list_t()
    result.items = items
    result.size = len(items)
    result._keepalive = (items, row_buffers)  # type: ignore[attr-defined]
    return result


def make_double_list_list_list(values):
    items = [make_double_list_list(item) for item in values]
    item_array = (ifcopenshell_double_list_list_t * len(items))(*items)
    result = ifcopenshell_double_list_list_list_t()
    result.items = item_array
    result.size = len(item_array)
