def last_error(lib, default="Unknown error"):
    fn = getattr(lib, _LAST_ERROR_NAME, None)
    if fn is None:
        return default
    raw = fn()
    if not raw:
        return default
    return raw.decode("utf-8", errors="replace")


def status_or_raise(lib, status, fallback):
    if status:
        return True
    raise_last_error(lib, fallback)


def last_error_kind(lib):
    return getattr(lib, _LAST_ERROR_KIND_NAME)()


def exception_for_error_kind(kind):
    return {
        IFCOPENSHELL_ERROR_VALUE: ValueError,
        IFCOPENSHELL_ERROR_TYPE: TypeError,
        IFCOPENSHELL_ERROR_NOT_IMPLEMENTED: NotImplementedError,
        IFCOPENSHELL_ERROR_KEY: KeyError,
    }.get(kind, RuntimeError)


def raise_last_error(lib, fallback):
    message = last_error(lib, fallback)
    raise exception_for_error_kind(last_error_kind(lib))(message)


def call_string(lib, fn, *args, decode=True, value_type=None):
    if value_type is None:
        value_type = ifcopenshell_string_t
    value = value_type()
    if not fn(*args, ctypes.byref(value)):
        return None
    return take_string(lib, value, decode=decode)


def call_string_list(lib, fn, *args, decode=True, value_type=None):
    if value_type is None:
        value_type = ifcopenshell_string_list_t
    value = value_type()
    if not fn(*args, ctypes.byref(value)):
        return None
    return take_string_list(lib, value, decode=decode)


def call_int32_list(lib, fn, *args):
    value = ifcopenshell_int32_list_t()
    if not fn(*args, ctypes.byref(value)):
        return None
    return take_int32_list(lib, value)


